-- EVT hook file for ability_list_menu_on_bluebg (VRFW_Host handlers, docs/framework/lua-hosts.md). Graft character_reforged_board (board_list_create_hooks.lua). Generated by research/scripts/menu_assemble.py; do not edit by hand.
-- Character Reforged › the skill board's aura list (ability_list_menu_on_bluebg, opened by an aura piece of the retail
-- board) while the «Crear …» rows are listed (graft character_reforged_board; docs/game/mods/all-miximaxed.md §7, owner
-- 2026-10-14). HOOK file (graft [[hooks]], shipped as is): it wraps the list's globals and calls them; no retail
-- function is replaced. Active only when the board's create entry passed the shown player (param
-- character_reforged_list_base, written by board_create_entry_hooks.lua before the list opens, removed after it):
--   * a «create» row: the item's own name, no counts, its aura type's icon (CharacterReforged.CreateCard.Row);
--   * its detail card: the item's own name and description, no template portrait / move (CreateCard.Detail);
--   * a retail Mix-Max row this player can not take (CreateCard.Allowed: the VR-Framework's owners / whitelist rule) and
--     a «create» row he may not be the base of (CreateCard.CreateAllowed: the avatar when the system's rule says
--     avatar_may_pair = false): greyed, and Aceptar on it plays the retail error sound and keeps the list open.
-- The shared rules are Character Reforged's lua\_all\character_reforged_create_card.lua (also the «Fantasy» skill
-- table's picker, graft ss2_menus). Definitions and wraps only at chunk load (no engine call).
do
  CharacterReforged_BoardList = CharacterReforged_BoardList or {}
  local List = CharacterReforged_BoardList
  List.KEY_BASE = 938944415                         -- character_reforged_list_base
  List.ITEM_LAYER = 1205526439                      -- team08_02_ability_list_item
  List.LIST_LAYER = 3520823522                      -- team08_01_ability_list
  List.ITEM_OF = 901208644                          -- (inventory handle) -> item id
  List.SOUND = 1917805374
  List.SE_REFUSED = 2086672038                      -- sy0003
  List.LOG = 2743311895                             -- CMND_CHARACTERREFORGED_CREATE_LOG (step, values…)
  List.base, List.focus, List.refused = 0, 0, {}

  function List.Card()
    local cr = rawget(_G, "CharacterReforged")
    return type(cr) == "table" and type(cr.CreateCard) == "table" and cr.CreateCard or nil
  end

  function List.WrapGlobal(name, make)
    List.wrapped = List.wrapped or {}
    if List.wrapped[name] then
      return
    end
    local current = _ENV[name]
    if current == nil then
      return
    end
    _ENV[name] = make(current)
    List.wrapped[name] = true
  end

  List.WrapGlobal("OnInit", function(previous)
    return function(...)
      List.base, List.focus, List.refused = 0, 0, {}
      pcall(function()
        if VRFW_Param.Has(List.KEY_BASE) then
          local h = VRFW_Param.Get(List.KEY_BASE)
          List.base = type(h) == "number" and h or 0
        end
        local card = List.Card()
        if card ~= nil then
          card.Reset()
        end
      end)
      return previous(...)
    end
  end)

  List.WrapGlobal("UpdateListItem", function(previous)
    return function(a1, a2, a3, ...)
      local r = table.pack(previous(a1, a2, a3, ...))
      local card = List.Card()
      if List.base ~= 0 and card ~= nil and a1 == List.ITEM_LAYER then
        pcall(function()
          local skill = card.U32(funcLuaCommand(List.ITEM_OF, a3))
          if skill == 0 then
            return
          end
          if card.IsCreate(skill) then
            card.Row(a1, a2, skill)
            if not card.CreateAllowed(skill, List.base) then
              List.refused[skill] = true
              if type(SetupGrayout) == "function" then
                SetupGrayout(a1, a2, 0.5)
              end
            end
          elseif not card.Allowed(skill, List.base) then
            List.refused[skill] = true
            if type(SetupGrayout) == "function" then
              SetupGrayout(a1, a2, 0.5)
            end
          end
        end)
      end
      return table.unpack(r, 1, r.n)
    end
  end)

  List.WrapGlobal("SendSkillIdToLua", function(previous)
    return function(a1, ...)
      List.focus = type(a1) == "number" and a1 or 0
      return previous(a1, ...)
    end
  end)

  -- Aceptar on a row this player can not take: the error sound, the list stays open
  List.WrapGlobal("OnEnter", function(previous)
    return function(a1, ...)
      local card = List.Card()
      if List.base ~= 0 and card ~= nil and a1 == List.LIST_LAYER and List.refused[card.U32(List.focus)] then
        funcLuaCommand(List.SOUND, List.SE_REFUSED)
        pcall(funcLuaCommand, List.LOG, "list refused", "player", List.base, "aura", List.focus)
        return
      end
      local r = table.pack(previous(a1, ...))
      -- a «create» row: the partner bank opens while the list closes (no board in between)
      if List.base ~= 0 and card ~= nil and a1 == List.LIST_LAYER and card.IsCreate(card.U32(List.focus)) then
        pcall(card.OpenBankEarly, List.base, card.U32(List.focus), nil)
      end
      return table.unpack(r, 1, r.n)
    end
  end)

  List.WrapGlobal("UpdateSkillDetailWindow", function(previous)
    return function(a1, ...)
      local r = table.pack(previous(a1, ...))
      local card = List.Card()
      if List.base ~= 0 and card ~= nil and type(a1) == "number" then
        pcall(card.Detail, card.U32(a1))
      end
      return table.unpack(r, 1, r.n)
    end
  end)
end
